CREATE TABLE "api_keys" ( "id" varchar NOT NULL PRIMARY KEY, "key_hash" varchar NOT NULL UNIQUE, "user_id" varchar NOT NULL, "spend_limit_micro_usd" bigint, "rpm_limit" bigint, "policy_id" varchar, "expires_at" varchar, "active" integer NOT NULL DEFAULT 1, "created_at" varchar NOT NULL, FOREIGN KEY ("user_id") REFERENCES "users" ("id") );
CREATE TABLE "checkpoint_evolution" ( "record_id" varchar(64) PRIMARY KEY, "scope_id" varchar(64) NOT NULL, "kind" varchar(32) NOT NULL, "session_key" varchar(64), "revision" bigint NOT NULL, "body" text NOT NULL , "installation_id" varchar(128) COLLATE BINARY, "tenant_id" varchar(128) COLLATE BINARY, "creator_principal_id" varchar(128) COLLATE BINARY);
CREATE TABLE "eval_admission_events" ( "sequence" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "result_id" varchar NOT NULL, "status" varchar NOT NULL, "reason" varchar NOT NULL, "authority_id" varchar NOT NULL, "created_at" varchar NOT NULL , "installation_id" varchar(128) COLLATE BINARY, "tenant_id" varchar(128) COLLATE BINARY, "creator_principal_id" varchar(128) COLLATE BINARY);
CREATE TABLE "eval_import_provenance" ( "installation_id" varchar(128) COLLATE BINARY NOT NULL, "tenant_id" varchar(128) COLLATE BINARY NOT NULL, "creator_principal_id" varchar(128) COLLATE BINARY NOT NULL, "snapshot_key" varchar(64) COLLATE BINARY NOT NULL, "manifest_sha256" varchar(64) COLLATE BINARY NOT NULL, "provenance_digest" varchar(64) COLLATE BINARY NOT NULL, "provenance_json" text NOT NULL, PRIMARY KEY ("snapshot_key") );
CREATE TABLE "eval_results" ( "result_id" varchar NOT NULL PRIMARY KEY, "eval_id" varchar NOT NULL, "idempotency_key" varchar NOT NULL, "authority_id" varchar NOT NULL, "evaluator_kind" varchar NOT NULL, "content_digest" varchar NOT NULL, "result_json" text NOT NULL, "created_at" varchar NOT NULL , "owner_user_id" varchar NOT NULL DEFAULT 'local', "installation_id" varchar(128) COLLATE BINARY, "tenant_id" varchar(128) COLLATE BINARY, "creator_principal_id" varchar(128) COLLATE BINARY);
CREATE TABLE "eval_snapshots" ( "evidence_root" varchar NOT NULL PRIMARY KEY, "manifest_json" text NOT NULL, "result_count" integer NOT NULL, "frozen_at" varchar NOT NULL , "owner_user_id" varchar NOT NULL DEFAULT 'local', "installation_id" varchar(128) COLLATE BINARY, "tenant_id" varchar(128) COLLATE BINARY, "creator_principal_id" varchar(128) COLLATE BINARY);
CREATE TABLE "eval_subjects" ( "eval_id" varchar NOT NULL PRIMARY KEY, "subject_id" varchar NOT NULL, "scope" varchar NOT NULL, "policy_digest" varchar NOT NULL, "holdout" boolean NOT NULL, "content_digest" varchar NOT NULL, "subject_json" text NOT NULL, "created_at" varchar NOT NULL , "owner_user_id" varchar NOT NULL DEFAULT 'local', "installation_id" varchar(128) COLLATE BINARY, "tenant_id" varchar(128) COLLATE BINARY, "creator_principal_id" varchar(128) COLLATE BINARY);
CREATE TABLE "provider_continuation_key_epoch" ( "singleton_id" integer NOT NULL PRIMARY KEY, "key_id" varchar NOT NULL, "created_at" varchar NOT NULL );
CREATE TABLE "provider_continuations" ( "continuation_identity" varchar NOT NULL PRIMARY KEY, "owner_identity" varchar NOT NULL, "ciphertext" text, "nonce" varchar, "target_fingerprint" varchar NOT NULL, "key_id" varchar NOT NULL, "cipher_version" integer NOT NULL, "created_at" varchar NOT NULL, "expires_at" varchar NOT NULL, "purge_after" varchar NOT NULL, "publication_state" varchar NOT NULL, "publication_generation" varchar NOT NULL, "publication_instance_id" varchar NOT NULL, "publication_lease_until" varchar NOT NULL, "installation_id" varchar(128) COLLATE BINARY, "tenant_id" varchar(128) COLLATE BINARY, "creator_principal_id" varchar(128) COLLATE BINARY, CHECK ("publication_state" IN ('provisional', 'delivering', 'active')), CHECK ("publication_generation" <> ''), CHECK ("publication_instance_id" <> ''), CHECK ("publication_lease_until" <> '') );
CREATE TABLE "requests" ( "request_id" varchar NOT NULL PRIMARY KEY, "user_id" varchar NOT NULL, "api_key_id" varchar NOT NULL, "model_id" varchar NOT NULL, "provider_id" varchar NOT NULL, "prompt_tokens" bigint NOT NULL, "completion_tokens" bigint NOT NULL, "reasoning_tokens" bigint NOT NULL, "cache_read_tokens" bigint NOT NULL DEFAULT 0, "cache_write_tokens" bigint NOT NULL DEFAULT 0, "estimated_charge_micro_usd" bigint NOT NULL DEFAULT 0, "streamed" integer NOT NULL DEFAULT 0, "latency_ms" bigint NOT NULL DEFAULT 0, "generation_time_ms" bigint NOT NULL DEFAULT 0, "error" varchar, "created_at" varchar NOT NULL , "uncached_input_tokens" bigint NOT NULL DEFAULT 0, "output_tokens" bigint NOT NULL DEFAULT 0, "usage_origin" varchar NOT NULL DEFAULT 'unknown', "raw_usage_json" text, "charge_status" varchar NOT NULL DEFAULT 'legacy_unknown', "charge_evidence_json" text, "reconciliation_status" varchar NOT NULL DEFAULT 'not_applicable', "reconciliation_attempts" integer NOT NULL DEFAULT 0, "reconciliation_last_error" text, "reconciliation_last_attempt_at" varchar, "authoritative_settled_at" varchar, "authoritative_receipt_json" text, "launch_id" varchar, "agent_harness" varchar, "controller_instance_id" varchar, "acp_session_id" varchar, "native_root_session_id" varchar, "native_agent_thread_id" varchar, "native_parent_agent_thread_id" varchar, "native_turn_id" varchar, "route_lease_id" varchar, "session_identity_json" text, "route_scope_id" varchar, "router_id" varchar, "binding_digest" varchar, "original_selector" varchar);
CREATE TABLE "seaql_migrations" ( "version" varchar NOT NULL PRIMARY KEY, "applied_at" bigint NOT NULL );
CREATE TABLE "tenancy_active_configurations" ( "tenant_id" varchar(128) COLLATE BINARY NOT NULL PRIMARY KEY, "revision_id" varchar(128) COLLATE BINARY NOT NULL, "authority_revision" bigint NOT NULL, FOREIGN KEY ("tenant_id", "revision_id") REFERENCES "tenancy_configurations" ("tenant_id", "revision_id") );
CREATE TABLE "tenancy_bindings" ( "tenant_id" varchar(128) COLLATE BINARY NOT NULL, "id" varchar(128) COLLATE BINARY NOT NULL, "principal_id" varchar(128) COLLATE BINARY NOT NULL, "revision" varchar(128) COLLATE BINARY NOT NULL, "role" varchar(128) COLLATE BINARY NOT NULL, "scope_json" text NOT NULL, "expires_at" text NOT NULL, "management_owner" varchar(128) COLLATE BINARY, "management_class" varchar(32) COLLATE BINARY, PRIMARY KEY ("tenant_id", "id"), FOREIGN KEY ("tenant_id") REFERENCES "tenancy_tenants" ("id"), FOREIGN KEY ("principal_id") REFERENCES "tenancy_principals" ("id") );
CREATE TABLE "tenancy_configurations" ( "tenant_id" varchar(128) COLLATE BINARY NOT NULL, "revision_id" varchar(128) COLLATE BINARY NOT NULL, "schema_version" integer NOT NULL, "document_json" text NOT NULL, "compiler_version" varchar(64) COLLATE BINARY NOT NULL, "content_digest" varchar(64) COLLATE BINARY NOT NULL, "compiled_json" text NOT NULL, "dependencies_json" text NOT NULL, "creator_principal_id" varchar(128) COLLATE BINARY NOT NULL, "authority_revision" bigint NOT NULL, "created_at" varchar(64) COLLATE BINARY NOT NULL, PRIMARY KEY ("tenant_id", "revision_id"), FOREIGN KEY ("tenant_id") REFERENCES "tenancy_tenants" ("id") );
CREATE TABLE "tenancy_continuation_epoch" ( "singleton" integer NOT NULL PRIMARY KEY, "installation_id" varchar(128) COLLATE BINARY NOT NULL, "key_id" varchar(64) COLLATE BINARY NOT NULL, "created_at" varchar(20) COLLATE BINARY NOT NULL );
CREATE TABLE "tenancy_credentials" ( "id" varchar(128) COLLATE BINARY NOT NULL PRIMARY KEY, "tenant_id" varchar(128) COLLATE BINARY NOT NULL, "principal_id" varchar(128) COLLATE BINARY NOT NULL, "binding_id" varchar(128) COLLATE BINARY, "revision" varchar(128) COLLATE BINARY NOT NULL, "key_hash" varchar(128) COLLATE BINARY NOT NULL UNIQUE, "state" varchar(128) COLLATE BINARY NOT NULL, "audit_reader" boolean NOT NULL, "permissions_json" text NOT NULL, "scope_json" text NOT NULL, "expires_at" text NOT NULL, "created_at" text NOT NULL, FOREIGN KEY ("tenant_id") REFERENCES "tenancy_tenants" ("id"), FOREIGN KEY ("principal_id") REFERENCES "tenancy_principals" ("id"), FOREIGN KEY ("tenant_id", "binding_id") REFERENCES "tenancy_bindings" ("tenant_id", "id") );
CREATE TABLE "tenancy_dispatch_intents" ( "installation_id" varchar(128) COLLATE BINARY NOT NULL, "tenant_id" varchar(128) COLLATE BINARY NOT NULL, "execution_id" varchar(128) COLLATE BINARY NOT NULL, "intent_json" text NOT NULL, "content_digest" varchar(64) COLLATE BINARY NOT NULL, "byte_count" bigint NOT NULL, PRIMARY KEY ("installation_id", "tenant_id", "execution_id") );
CREATE TABLE "tenancy_execution_receipts" ( "installation_id" varchar(128) COLLATE BINARY NOT NULL, "tenant_id" varchar(128) COLLATE BINARY NOT NULL, "execution_id" varchar(128) COLLATE BINARY NOT NULL, "principal_id" varchar(128) COLLATE BINARY NOT NULL, "correlation_id" varchar(128) COLLATE BINARY NOT NULL, "receipt_json" text NOT NULL, "content_digest" varchar(64) COLLATE BINARY NOT NULL, "disposition_json" text NOT NULL, "byte_count" bigint NOT NULL, "unknown_outcome" boolean NOT NULL, "recorded_at" varchar(20) COLLATE BINARY NOT NULL, "storage_kind" integer NOT NULL DEFAULT 0 CHECK ("storage_kind" IN (0, 1)), "receipt_format" integer NOT NULL DEFAULT 1, PRIMARY KEY ("installation_id", "tenant_id", "execution_id") );
CREATE TABLE "tenancy_installation" ( "singleton" integer NOT NULL PRIMARY KEY, "installation_id" varchar(128) COLLATE BINARY NOT NULL UNIQUE, "schema_version" integer NOT NULL, "authority_revision" bigint NOT NULL, "operation_ids" integer NOT NULL, "safety_operation_ids" integer NOT NULL, "saturated" boolean NOT NULL, "created_at" text NOT NULL );
CREATE TABLE "tenancy_oauth_slots" ( "slot_key" varchar(64) COLLATE BINARY NOT NULL, "installation_id" varchar(128) COLLATE BINARY NOT NULL, "owner_kind" varchar(32) COLLATE BINARY NOT NULL, "owner_id" varchar(128) COLLATE BINARY NOT NULL, "credential_resource_id" varchar(128) COLLATE BINARY NOT NULL, "authority_revision" varchar(128) COLLATE BINARY NOT NULL, "generation" bigint NOT NULL, "state" varchar(32) COLLATE BINARY NOT NULL, "metadata_json" text NOT NULL, "payload_json" text NOT NULL, "content_digest" varchar(64) COLLATE BINARY NOT NULL, "pending_tenant_id" varchar(128) COLLATE BINARY, "pending_execution_id" varchar(128) COLLATE BINARY, PRIMARY KEY ("slot_key") );
CREATE TABLE "tenancy_operations" ( "installation_id" varchar(128) COLLATE BINARY NOT NULL, "principal_id" varchar(128) COLLATE BINARY NOT NULL, "operation_id" varchar(128) COLLATE BINARY NOT NULL, "tenant_id" varchar(128) COLLATE BINARY, "authority_class" varchar(128) COLLATE BINARY NOT NULL, "read_context_json" text NOT NULL, "hash_version" integer NOT NULL, "command_digest" varchar(128) COLLATE BINARY NOT NULL, "result_json" text NOT NULL, "response_json" text NOT NULL, "created_at" text NOT NULL, "safety" boolean NOT NULL, PRIMARY KEY ("installation_id", "principal_id", "operation_id") );
CREATE TABLE "tenancy_principals" ( "id" varchar(128) COLLATE BINARY NOT NULL PRIMARY KEY, "revision" varchar(128) COLLATE BINARY NOT NULL, "issuer" varchar(256) COLLATE BINARY NOT NULL, "subject" varchar(256) COLLATE BINARY NOT NULL, "created_at" text NOT NULL, CONSTRAINT "uq_tenancy_principal_subject" UNIQUE ("issuer", "subject") );
CREATE TABLE "tenancy_receipt_archive" ( "installation_id" varchar(128) COLLATE BINARY NOT NULL, "tenant_id" varchar(128) COLLATE BINARY NOT NULL, "execution_id" varchar(128) COLLATE BINARY NOT NULL, "format_version" bigint NOT NULL, "codec" bigint NOT NULL, "receipt_bytes" bigint NOT NULL, "usage_bytes" bigint NOT NULL, "payload" blob NOT NULL, PRIMARY KEY ("installation_id", "tenant_id", "execution_id") );
CREATE TABLE "tenancy_receipt_auxiliary" ( "installation_id" varchar(128) COLLATE BINARY NOT NULL, "tenant_id" varchar(128) COLLATE BINARY NOT NULL, "execution_id" varchar(128) COLLATE BINARY NOT NULL, "receipt_digest" varchar(64) COLLATE BINARY NOT NULL, "evidence_json" text NOT NULL, "evidence_digest" varchar(64) COLLATE BINARY NOT NULL, "unknown_outcome" boolean NOT NULL, PRIMARY KEY ("installation_id", "tenant_id", "execution_id") );
CREATE TABLE "tenancy_resource_lifecycle" ( "owner_kind" varchar(32) COLLATE BINARY NOT NULL, "owner_id" varchar(128) COLLATE BINARY NOT NULL, "resource_kind" varchar(32) COLLATE BINARY NOT NULL, "resource_id" varchar(128) COLLATE BINARY NOT NULL, "revision_id" varchar(128) COLLATE BINARY NOT NULL, "installation_id" varchar(128) COLLATE BINARY NOT NULL, "is_head" boolean NOT NULL, "revoked" boolean NOT NULL, "authority_revision" bigint NOT NULL, PRIMARY KEY ("owner_kind", "owner_id", "resource_kind", "resource_id", "revision_id") );
CREATE TABLE "tenancy_resource_revisions" ( "owner_kind" varchar(32) COLLATE BINARY NOT NULL, "owner_id" varchar(128) COLLATE BINARY NOT NULL, "resource_kind" varchar(32) COLLATE BINARY NOT NULL, "resource_id" varchar(128) COLLATE BINARY NOT NULL, "revision_id" varchar(128) COLLATE BINARY NOT NULL, "compiler_version" varchar(64) COLLATE BINARY NOT NULL, "payload_json" text NOT NULL, "dependency_json" text NOT NULL, "content_digest" varchar(64) COLLATE BINARY NOT NULL, "created_at" varchar(64) COLLATE BINARY NOT NULL, PRIMARY KEY ("owner_kind", "owner_id", "resource_kind", "resource_id", "revision_id") );
CREATE TABLE "tenancy_tenants" ( "id" varchar(128) COLLATE BINARY NOT NULL PRIMARY KEY, "revision" varchar(128) COLLATE BINARY NOT NULL, "state" varchar(128) COLLATE BINARY NOT NULL, "created_at" text NOT NULL );
CREATE TABLE "tenancy_unknown_obligations" ( "installation_id" varchar(128) COLLATE BINARY NOT NULL, "tenant_id" varchar(128) COLLATE BINARY NOT NULL, "execution_id" varchar(128) COLLATE BINARY NOT NULL, "source_mask" integer NOT NULL CHECK ("source_mask" BETWEEN 1 AND 7), "first_seconds" bigint NOT NULL, "first_nanos" integer NOT NULL CHECK ("first_nanos" BETWEEN 0 AND 999999999), "due_seconds" bigint NOT NULL, "due_nanos" integer NOT NULL CHECK ("due_nanos" BETWEEN 0 AND 999999999), "escalated" integer NOT NULL CHECK ("escalated" IN (0, 1)), PRIMARY KEY ("installation_id", "tenant_id", "execution_id") );
CREATE TABLE "tenancy_usage_evidence" ( "installation_id" varchar(128) COLLATE BINARY NOT NULL, "tenant_id" varchar(128) COLLATE BINARY NOT NULL, "execution_id" varchar(128) COLLATE BINARY NOT NULL, "schema_version" integer NOT NULL, "receipt_digest" varchar(64) COLLATE BINARY NOT NULL, "evidence_digest" varchar(64) COLLATE BINARY NOT NULL, "evidence_json" text NOT NULL, "byte_count" bigint NOT NULL, "storage_kind" integer NOT NULL DEFAULT 0 CHECK ("storage_kind" IN (0, 1)), PRIMARY KEY ("installation_id", "tenant_id", "execution_id") );
CREATE TABLE "trajectory_episodes" ( "episode_id" varchar NOT NULL PRIMARY KEY, "owner_user_id" varchar NOT NULL, "correlation_digest" varchar NOT NULL, "correlation_key_id" varchar NOT NULL, "correlation_source" varchar NOT NULL, "history_completeness" varchar NOT NULL, "next_sequence" bigint NOT NULL, "first_captured_at" varchar NOT NULL, "last_captured_at" varchar NOT NULL, "closed_at" varchar, "latest_request_id" varchar , "installation_id" varchar(128) COLLATE BINARY, "tenant_id" varchar(128) COLLATE BINARY, "creator_principal_id" varchar(128) COLLATE BINARY, "logical_identity_json" varchar(8192) COLLATE BINARY);
CREATE TABLE "trajectory_events" ( "event_id" varchar NOT NULL PRIMARY KEY, "owner_user_id" varchar NOT NULL, "episode_id" varchar NOT NULL, "request_id" varchar, "sequence" bigint NOT NULL, "kind" varchar NOT NULL, "event_json" text NOT NULL, "content_digest" varchar NOT NULL, "captured_at" varchar NOT NULL , "installation_id" varchar(128) COLLATE BINARY, "tenant_id" varchar(128) COLLATE BINARY, "creator_principal_id" varchar(128) COLLATE BINARY);
CREATE TABLE "trajectory_outbox" ( "outbox_id" varchar NOT NULL PRIMARY KEY, "owner_user_id" varchar NOT NULL, "topic" varchar NOT NULL, "payload_json" text NOT NULL, "payload_digest" varchar NOT NULL, "attempts" bigint NOT NULL DEFAULT 0, "created_at" varchar NOT NULL, "delivered_at" varchar , "installation_id" varchar(128) COLLATE BINARY, "tenant_id" varchar(128) COLLATE BINARY, "creator_principal_id" varchar(128) COLLATE BINARY, "logical_identity_json" varchar(8192) COLLATE BINARY);
CREATE TABLE "trajectory_prefix_index" ( "owner_user_id" varchar NOT NULL, "full_input_digest" varchar NOT NULL, "episode_id" varchar NOT NULL, "ambiguous" boolean NOT NULL, "installation_id" varchar(128) COLLATE BINARY, "tenant_id" varchar(128) COLLATE BINARY, "creator_principal_id" varchar(128) COLLATE BINARY, "logical_identity_json" varchar(8192) COLLATE BINARY, PRIMARY KEY ("owner_user_id", "full_input_digest") );
CREATE TABLE "trajectory_requests" ( "request_id" varchar NOT NULL PRIMARY KEY, "owner_user_id" varchar NOT NULL, "episode_id" varchar NOT NULL, "start_event_id" varchar NOT NULL, "settlement_event_id" varchar, "settlement_outbox_id" varchar, "full_input_digest" varchar NOT NULL, "native_parent_id" varchar, "protocol" varchar NOT NULL, "status" varchar NOT NULL , "installation_id" varchar(128) COLLATE BINARY, "tenant_id" varchar(128) COLLATE BINARY, "creator_principal_id" varchar(128) COLLATE BINARY, "logical_identity_json" varchar(8192) COLLATE BINARY);
CREATE TABLE "users" ( "id" varchar NOT NULL PRIMARY KEY, "created_at" varchar NOT NULL );
