CREATE INDEX "idx_eval_subjects_owner" ON "eval_subjects" ("owner_user_id");
CREATE INDEX "idx_eval_subjects_scope_id" ON "eval_subjects" ("installation_id", "tenant_id", "eval_id");
CREATE INDEX "idx_legacy33_3_scope" ON "checkpoint_evolution" ("installation_id", "tenant_id");
CREATE UNIQUE INDEX "idx_provider_continuations_owner" ON "provider_continuations" ("owner_identity", "continuation_identity");
