CREATE INDEX "idx_requests_launch_id" ON "requests" ("launch_id");
CREATE INDEX "idx_requests_user_created" ON "requests" ("user_id", "created_at");
CREATE INDEX "idx_tenancy_credentials_directory" ON "tenancy_credentials" ("tenant_id", "id");
CREATE INDEX "idx_tenancy_credentials_state" ON "tenancy_credentials" ("state", "tenant_id");
